import{_ as o,o as a,c as r,a2 as n}from"./chunks/framework.C4u7U0Dw.js";const _=JSON.parse('{"title":"第 18 章 如何进行多 Agent 系统设计（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第18章 如何进行多 Agent 系统设计（易懂版）.md","filePath":"easy/第18章 如何进行多 Agent 系统设计（易懂版）.md"}'),e={name:"easy/第18章 如何进行多 Agent 系统设计（易懂版）.md"};function s(l,t,i,g,u,h){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="第-18-章-如何进行多-agent-系统设计-易懂版" tabindex="-1">第 18 章 如何进行多 Agent 系统设计（易懂版） <a class="header-anchor" href="#第-18-章-如何进行多-agent-系统设计-易懂版" aria-label="Permalink to &quot;第 18 章 如何进行多 Agent 系统设计（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 18 章 如何进行多 Agent 系统设计（完整版）](../../bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 18 章 如何进行多 Agent 系统设计.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>组队干活谁都会喊，但&quot;怎么设计一支好用的 AI 团队&quot;是门手艺——这章讲设计原则。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>组乐队不是&quot;拉几个人上台&quot;就行：<strong>谁主唱、谁吉他、谁鼓，谁定调、谁收尾</strong>——角色清楚了才叫乐队，否则叫噪音。</p><p>多 Agent 系统设计 = <strong>给每个 AI 定角色、定分工、定协作方式</strong>。</p><h2 id="核心就-3-件事" tabindex="-1">核心就 3 件事 <a class="header-anchor" href="#核心就-3-件事" aria-label="Permalink to &quot;核心就 3 件事&quot;">​</a></h2><ol><li><strong>角色要单</strong>：每个成员<strong>只干一件事</strong>（只写文案，或只管检查）——角色越纯粹，干得越稳。</li><li><strong>边界要清</strong>：谁负责哪块、谁的产出给谁——<strong>职责不清 = 互相甩锅</strong>。</li><li><strong>协作要有序</strong>：要么<strong>并行</strong>（互不依赖的活同时干），要么<strong>流水线</strong>（上游产出喂给下游）。</li></ol><h2 id="设计五步" tabindex="-1">设计五步 <a class="header-anchor" href="#设计五步" aria-label="Permalink to &quot;设计五步&quot;">​</a></h2><ol><li><strong>拆任务</strong>：整个目标切成几块；</li><li><strong>定角色</strong>：每块给一个&quot;专职&quot;的 Agent；</li><li><strong>画流程</strong>：谁先谁后、谁把结果传给谁；</li><li><strong>定检查</strong>：哪几个环节必须验（重要输出别直接过）；</li><li><strong>留后门</strong>：出问题能喊停、能重跑某一步。</li></ol><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p>设计&quot;每周行业报告&quot;系统：</p><ul><li><strong>A（收集员）</strong>：抓资讯，出&quot;原始素材包&quot;；</li><li><strong>B（分析师）</strong>：读素材包，出&quot;要点分析&quot;；</li><li><strong>C（审稿员）</strong>：检查 B 的分析是否跑题、有无数据错误；</li><li><strong>顺序</strong>：A → B → C，串行流水线。</li></ul></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 角色重叠——<strong>两个 Agent 都&quot;负责写&quot;，最后两版对不上</strong>；</li><li>❌ 没有检查环节——<strong>流水线跑完才发现源头就错了</strong>；</li><li>❌ 一上来就复杂——<strong>先用 2-3 个 Agent 跑通，再加人</strong>。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>多 Agent 设计 = 角色单 + 边界清 + 流程有序 + 关键环节有检查。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>画一张你下周要做的项目的&quot;分工图&quot;：<strong>几个人？各干什么？谁先谁后？</strong> 画得出来，就组队吧。</p><p>👉 [下一章：自动化工作流的可靠性（易懂版）](第19章 自动化工作流的可靠性（易懂版）.md)</p>',20)])])}const c=o(e,[["render",s]]);export{_ as __pageData,c as default};
